"use client"

import React from "react"
import {
  Target,
  UserCheck,
  Zap,
  Feather,
  Calendar,
  Share2,
  MessageSquareHeart,
  Award,
  CheckCircle2,
  ArrowRight
} from "lucide-react"

export interface WorkflowStepUI {
  key: string
  stepNumber: number
  label: string
  actor: string
  completed: boolean
}

interface TriPartyWorkflowBannerProps {
  goals?: any[]
  consultations?: any[]
  reflections?: any[]
  actionItems?: any[]
  termEvaluations?: any[]
  parentExchanges?: any[]
  viewerRole: "TEACHER" | "STUDENT" | "PARENT"
}

export default function TriPartyWorkflowBanner({
  goals = [],
  consultations = [],
  reflections = [],
  actionItems = [],
  termEvaluations = [],
  parentExchanges = [],
  viewerRole
}: TriPartyWorkflowBannerProps) {
  const hasGoals = goals.some(g => Boolean(g?.targetText))
  const isAdvisorReviewed = goals.some(
    g =>
      g?.signedByTeacher ||
      g?.teacherComment ||
      g?.advisorReviewStatus === "CONFIRMED" ||
      g?.advisorReviewStatus === "NEEDS_ADJUSTMENT"
  )
  const hasActions =
    actionItems.some(a => a?.status === "COMPLETED" || a?.status === "IN_PROGRESS" || a?.evidenceNotes) ||
    goals.some(
      g =>
        Array.isArray(g?.actions) &&
        g.actions.some((a: any) => a?.status === "DOING" || a?.status === "DONE" || a?.status === "COMPLETED" || a?.evidenceNotes)
    )
  const hasReflections =
    reflections.length > 0 || consultations.some(c => Boolean(c?.studentReflection))
  const hasSession = consultations.length > 0
  const hasSharedFollowUp = consultations.some(
    c => c?.shareWithParent !== false && (c?.nextActions || c?.parentSharedSummary || c?.notes)
  )
  const hasParentFeedback =
    goals.some(g => g?.signedByParent || g?.parentMessage) ||
    consultations.some(c => c?.parentAcknowledged || c?.parentFeedback) ||
    parentExchanges.length > 0
  const hasProgressReview = termEvaluations.length > 0

  const steps = [
    {
      key: "STUDENT_GOAL",
      shortLabel: "1. Mục tiêu SMART",
      actorBadge: "Học sinh",
      completed: hasGoals,
      icon: Target
    },
    {
      key: "ADVISOR_REVIEW",
      shortLabel: "2. CVHT xác nhận",
      actorBadge: "Cố vấn",
      completed: isAdvisorReviewed,
      icon: UserCheck
    },
    {
      key: "STUDENT_ACTION",
      shortLabel: "3. Hành động 7 ngày",
      actorBadge: "Học sinh",
      completed: hasActions,
      icon: Zap
    },
    {
      key: "REFLECTION",
      shortLabel: "4. Tự phản tư",
      actorBadge: "Học sinh",
      completed: hasReflections,
      icon: Feather
    },
    {
      key: "ADVISORY_SESSION",
      shortLabel: "5. Phiên gặp 1:1",
      actorBadge: "CVHT ⇄ HS",
      completed: hasSession,
      icon: Calendar
    },
    {
      key: "SHARED_FOLLOW_UP",
      shortLabel: "6. Chia sẻ PHHS",
      actorBadge: "CVHT → PH",
      completed: hasSharedFollowUp,
      icon: Share2
    },
    {
      key: "PARENT_FEEDBACK",
      shortLabel: "7. PHHS phản hồi",
      actorBadge: "Phụ huynh",
      completed: hasParentFeedback,
      icon: MessageSquareHeart
    },
    {
      key: "PROGRESS_REVIEW",
      shortLabel: "8. Đánh giá tiến bộ",
      actorBadge: "3 Bên",
      completed: hasProgressReview,
      icon: Award
    }
  ]

  const completedCount = steps.filter(s => s.completed).length
  const progressPercent = Math.round((completedCount / steps.length) * 100)

  return (
    <div className="bg-white rounded-3xl p-4 sm:p-5 border border-slate-200/90 shadow-xs space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <span className="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-[#E6F6F5] text-[#003B3A] border border-teal-200">
            Đồng bộ nghiệp vụ 3 bên
          </span>
          <span className="text-xs font-extrabold text-slate-700">
            Chu trình Cố vấn Học tập Khép kín (8 Bước)
          </span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-28 h-2 bg-slate-100 rounded-full overflow-hidden border border-slate-200">
            <div
              className="h-full bg-gradient-to-r from-[#003B3A] to-[#01A49D] transition-all duration-500"
              style={{ width: `${progressPercent}%` }}
            />
          </div>
          <span className="text-xs font-black text-[#003B3A]">
            {completedCount}/{steps.length} mốc ({progressPercent}%)
          </span>
        </div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-8 gap-2">
        {steps.map((step, idx) => {
          const Icon = step.icon
          const isCurrent = !step.completed && (idx === 0 || steps[idx - 1].completed)
          return (
            <div
              key={step.key}
              className={`p-2.5 rounded-2xl border text-left transition-all flex flex-col justify-between gap-1.5 ${
                step.completed
                  ? "bg-emerald-50/70 border-emerald-200 text-emerald-950"
                  : isCurrent
                  ? "bg-amber-50/80 border-amber-300 text-amber-950 ring-1 ring-amber-300"
                  : "bg-slate-50/70 border-slate-200/80 text-slate-500"
              }`}
            >
              <div className="flex items-center justify-between gap-1">
                <span
                  className={`w-6 h-6 rounded-lg flex items-center justify-center text-xs font-black ${
                    step.completed
                      ? "bg-emerald-600 text-white"
                      : isCurrent
                      ? "bg-amber-500 text-slate-950"
                      : "bg-slate-200 text-slate-600"
                  }`}
                >
                  {step.completed ? <CheckCircle2 className="w-3.5 h-3.5" /> : <Icon className="w-3.5 h-3.5" />}
                </span>
                <span className="text-[9px] font-black uppercase px-1.5 py-0.5 rounded bg-white/80 border border-slate-200/70 text-slate-600">
                  {step.actorBadge}
                </span>
              </div>
              <div className="text-[11px] font-extrabold leading-tight">
                {step.shortLabel}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}
